head.script:
scwin.__setData = function() {
    var arr = [];
    arr.push(xml_param);
    if (localStorage.getItem("array")) {
        arr = JSON.parse(localStorage.getItem("array"));
        if (arr.length < 2) {
            arr.push(xml_param);
        } else {
            arr.length = 0;
            arr[0] = xml_param;
        }
    }
    localStorage.setItem("array", JSON.stringify(arr));
}
scwin.hello = function() {
    alert("hello");
};
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if(WebSquare._xv !== "SP5"){requires("uiplugin.popup");}
    window.xml_param = $w.getPopupParam();
    //Set data localStorage
    scwin.__setData();
    textarea1.setValue(xml_param);
    window.dataObject_param1 = $w.getParameter("param1");
    textarea2.setValue(JSON.stringify(dataObject_param1));
    window.dataObject_param2 = $w.getParameter("param2");
    textarea3.setValue(JSON.stringify(dataObject_param2));
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
